# Test hypothesis: isolated cells have no output pattern
target_in = [
    [0, 0, 3],
    [3, 3, 0],
    [0, 3, 0]
]

# Find ortho-isolated cells
ortho_connected = set()
for r in range(3):
    for c in range(3):
        if target_in[r][c] != 0:
            # Check orthogonal neighbors
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 3 and 0 <= nc < 3:
                    if target_in[nr][nc] != 0:
                        ortho_connected.add((r,c))
                        break

print("Ortho-connected cells:", sorted(ortho_connected))
print("Ortho-isolated cells:", sorted(set((r,c) for r in range(3) for c in range(3) if target_in[r][c] != 0) - ortho_connected))

# Construct solution: only ortho-connected cells get corner patterns
sol = [[0]*9 for _ in range(9)]
val = 3

for r, c in ortho_connected:
    if target_in[r][c] == val:
        sol[3*r][3*c] = val
        sol[3*r][3*c+2] = val
        sol[3*r+2][3*c] = val
        sol[3*r+2][3*c+2] = val

print("\nSolution (isolated cells excluded):")
for row in sol:
    print(row)

